export function makeSnapshot(
  overrides: Partial<SlackWorkspaceSnapshot> = {},
): SlackWorkspaceSnapshot {
  return {
    teamId: "T_EXAMPLE",
    teamName: "Example Workspace",
    teamDomain: "example-workspace",
    teamUrl: "https://example-workspace.slack.com/",
    selfUserId: "U_SELF",
    users,
    conversations,
    ...overrides,
  };
}
